"use strict";
/* Audit every source node and every reader-facing nested field in both locales.
 * Data and English projections are generated by build_language.py before this test.
 * Source symbols, source code, annotations, equations and paths remain verbatim.
 */
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const ROOT = path.resolve(__dirname, "../..");
const read = p => fs.readFileSync(path.join(ROOT, p), "utf8");
const data = JSON.parse(read("harness/visualization/data.js")
  .split("window.OPENRESEARCH_ATLAS = ")[1].trim().replace(/;\s*$/, ""));
const window = {};
vm.runInNewContext(read("harness/visualization/locale-data.js"), {window});
const locales = window.SAEBASE_ATLAS_LOCALES;
assert.equal(locales.project, "SAEBase");
const original = JSON.parse(JSON.stringify(data));
window.OPENRESEARCH_ATLAS = data;
window.dispatchEvent = () => {};
vm.runInNewContext(read("harness/visualization/locale-runtime.js"), {
  window, Event: class { constructor(type) { this.type = type; } }
});
const localize = window.SAEBASE_ATLAS_SET_NODE_LANGUAGE;
assert.equal(typeof localize, "function");
localize("en");

const cjk = /[\u3400-\u9fff]/;
const replacement = /\uFFFD|English translation unavailable|中文翻译待补充|its behavior is defined in the source|Browse \d+ source-backed child interfaces/i;
const technical = new Set(["code", "signature", "assignment", "source", "source_symbol",
  "symbol_id", "path", "line", "expressions", "default", "file", "source_path",
  "function_id", "id"]);
const prose = new Set(["title", "summary", "description", "reader_explanation",
  "technical_description", "why_it_matters", "label", "meaning", "purpose",
  "note", "caption", "value"]);
const errors = [], counts = {nodes: 0, attributes: 0, meanings: 0, translatedFields: 0};
function inspect(zh, en, location, key = "", verbatim = false) {
  if (typeof zh === "string") {
    if (!cjk.test(zh) || !prose.has(key) || verbatim || technical.has(key)) return;
    counts.translatedFields++;
    if (typeof en !== "string" || !en.trim() || cjk.test(en) || replacement.test(en)) {
      errors.push(location + " (" + key + ") => " + String(en).slice(0, 90));
    }
    return;
  }
  if (Array.isArray(zh)) {
    if (!Array.isArray(en) || en.length !== zh.length) {
      errors.push(location + " array dimensions changed");
      return;
    }
    for (let i = 0; i < zh.length; i++)
      inspect(zh[i], en[i], location + "[" + i + "]", key, verbatim);
    return;
  }
  if (!zh || typeof zh !== "object") return;
  if (!en || typeof en !== "object") {
    errors.push(location + " missing English object");
    return;
  }
  for (const [field, originalValue] of Object.entries(zh)) {
    if (technical.has(field)) continue;
    const isVerbatim = verbatim || (zh.type === "code" && field === "value") ||
      (zh.type === "formula" && field === "value");
    inspect(originalValue, en[field], location + "." + field, field, isVerbatim);
  }
}
for (const [view, graph] of Object.entries(original)) {
  const actual = new Map(data[view].nodes.map(n => [n.id, n]));
  assert.equal(graph.nodes.length, actual.size, "Node count changed in " + view);
  for (const zh of graph.nodes) {
    const en = actual.get(zh.id);
    if (!en) { errors.push(view + "/" + zh.id + " missing node"); continue; }
    const at = view + "/" + zh.id;
    counts.nodes++;
    for (const key of ["title", "summary", "description"]) {
      assert(typeof en[key] === "string" && en[key].trim(), at + "." + key);
      if (cjk.test(en[key]) || replacement.test(en[key]))
        errors.push(at + "." + key + " has invalid English prose");
    }
    inspect(zh.reader_explanation, en.reader_explanation, at, "reader_explanation");
    inspect(zh.technical_description, en.technical_description, at, "technical_description");
    inspect(zh.why_it_matters, en.why_it_matters, at, "why_it_matters");
    inspect(zh.attributes, en.attributes, at + ".attributes", "attributes");
    for (const block of en.attributes || []) {
      counts.attributes++;
      const items = [];
      if (block.interface) items.push(block.interface);
      if (block.methods) items.push(...block.methods);
      for (const iface of items)
        counts.meanings += (iface.parameters || []).length + (iface.returns ? 1 : 0);
    }
    if (zh.facts) {
      for (const [name, value] of Object.entries(zh.facts)) {
        const translation = ({
          "设备名称": "Device name", "驱动版本": "Driver version",
          "命令标识": "Command identifier", "Python 版本": "Python version",
          "网络条件": "Network status", "沙箱条件": "Sandbox environment"
        })[name] || name;
        assert(Object.prototype.hasOwnProperty.call(en.facts, translation),
          at + ".facts." + name + " lacks translated key");
        if (typeof value === "string" && cjk.test(value) &&
          (cjk.test(en.facts[translation]) || !en.facts[translation].trim()))
          errors.push(at + ".facts." + name + " lacks translated value");
      }
    }
  }
}
assert.deepEqual(Object.keys(data).sort(),
  ["core","knowledge","code","environment","context"].sort());
// Switching back must reconstruct the original Chinese source, not an English overlay.
localize("zh");
for (const [view, graph] of Object.entries(original)) {
  for (let i = 0; i < graph.nodes.length; i++) {
    for (const field of ["title", "summary", "description", "reader_explanation",
      "technical_description", "why_it_matters", "aliases", "attributes", "facts"]) {
      assert.equal(JSON.stringify(data[view].nodes[i][field]),
        JSON.stringify(graph.nodes[i][field]),
        "Chinese round-trip changed " + view + "/" + graph.nodes[i].id + "." + field);
    }
  }
}
assert.equal(counts.nodes, Object.values(original).reduce((n, t) => n + t.nodes.length, 0));
assert(counts.translatedFields > counts.nodes * 2, "Nested translation coverage unexpectedly dropped");
assert.equal(errors.length, 0,
  "Bilingual Atlas nested-field audit found " + errors.length + " defects:\n" +
  errors.slice(0, 40).join("\n"));

 // The structural test above restores Chinese; switch to English before
 // checking the English action summaries against those saved Chinese records.
 localize("en");
 // Semantic parity requires source-derived actions, not only nonempty English.
 // The paired Chinese source explicitly states these operations.
 const chineseCode = new Map(original.code.nodes.map(n => [n.id, n]));
 const englishCode = new Map(data.code.nodes.map(n => [n.id, n]));
 const exactPairs = [
   ["code:function:datasets.GreaterThan.GreaterThan:attach_greater_than_token_ids",
     "Attach token IDs to numerical comparison examples."],
   ["code:function:datasets.MMLUPro.MMLUPro:attach_distractors",
     "Attach distractor options to multiple-choice examples."],
   ["code:function:datasets.GreaterThan.tokenize:strategy_for_model_key",
     "Select the tokenization strategy for the chosen model."],
 ];
 for (const [id, meaning] of exactPairs) {
   assert(chineseCode.has(id) && englishCode.has(id), "Missing source identity " + id);
   assert.equal(englishCode.get(id).summary, meaning,
     "English summary must represent the operation in the Chinese source: " + id);
 }
 let translatedResponsibilities = 0;
 let sourceResponsibilities = 0;
 for (const [id, zh] of chineseCode) {
   const line = String(zh.summary || "");
   if (!/^负责.+；源码依据和调用参数可在节点的展开说明中查看。$/.test(line))
     continue;
   sourceResponsibilities++;
   const en = englishCode.get(id);
   if (en && !/^Inspect .+ interface for /.test(en.summary))
     translatedResponsibilities++;
 }
 assert.equal(translatedResponsibilities, sourceResponsibilities,
   "Some Chinese Code responsibilities fell back to mechanical source-symbol descriptions");

console.log("SAEBase bilingual semantic field audit", counts);
